from datetime import datetime


class Scheduler:
    def __init__(self) -> None:
        self._appointments = {}  # id -> dict(patient, doctor, start, end)
        self._next_id = 1

    def _overlaps(self, start1, end1, start2, end2) -> bool:
        # Touching intervals do not overlap.
        return start1 < end2 and start2 < end1

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        if start < now:
            raise ValueError("Cannot book an appointment in the past.")
        if end <= start:
            raise ValueError("End time must be after start time.")

        for appt in self._appointments.values():
            if appt["doctor"] == doctor and self._overlaps(
                start, end, appt["start"], appt["end"]
            ):
                raise ValueError(
                    "Doctor is not available for the requested time slot."
                )

        for appt in self._appointments.values():
            if appt["patient"] == patient and appt["start"] > now:
                raise ValueError(
                    "Patient already has an upcoming appointment."
                )

        appointment_id = self._next_id
        self._next_id += 1
        self._appointments[appointment_id] = {
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end,
        }
        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        if appointment_id not in self._appointments:
            raise ValueError(f"Unknown appointment id: {appointment_id}")
        del self._appointments[appointment_id]

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        for appt in self._appointments.values():
            if appt["doctor"] == doctor and self._overlaps(
                start, end, appt["start"], appt["end"]
            ):
                return False
        return True
